const care24ReceptionServer='https://care24-hospital-hub.samganid5197259555.chatgpt.site';
if(location.hostname==='127.0.0.1'||location.hostname==='localhost')location.replace(care24ReceptionServer+'/'+location.search+location.hash);
const diseases=['노인성 질환(치매, 뇌질환, 파킨슨)','폐질환','당뇨질환','투석질환','안과질환','호스피스·완화의료'];
const orthopedicDiseases=['골절','관절·근골격계질환','척추질환','골다공증','정형외과 수술 후 회복·재활'];
const diseasesFor=h=>/정형|관절|척추|수지접합/.test(h?.specialty||'')?orthopedicDiseases:diseases;
const caregiverOptionsFor=h=>[...diseases.map(x=>x+' 전문간병사'),...(/정형|관절|척추|수지접합/.test(h?.specialty||'')?['정형외과질환 전문간병사']:[])];
const key='care24_requests_v1';
const load=()=>JSON.parse(localStorage.getItem(key)||'[]');
const save=v=>localStorage.setItem(key,JSON.stringify(v));
const app=document.querySelector('#app');
const findFacility=id=>hospitals.find(x=>x.id===id)||careFacilities.find(x=>x.id===id);
const hospitalCards=(rows=hospitals)=>rows.map(h=>`<article class="card hospital" onclick="location.hash='hospital/${h.id}'"><span class="badge">${h.region} · ${h.type}</span><h3 class="hospital-card-name"><img class="hospital-name-icon" src="assets/care24-brand.webp?v=20261003-logo2" alt="간병24"> <span>${h.name}</span></h3><p>${h.city}${h.veterans?' · 보훈의료':h.specialty?` · ${h.specialty} 전문`:''}${h.hospice?` · 호스피스 ${h.hospiceServices}`:''} · 환자·보호자 의뢰 · 간병인 신청</p><span class="hospital-card-open">통합간병 앱 열기 →</span></article>`).join('');
function home(){app.innerHTML=`<section class="hero"><div><p class="eyebrow">전국 병원 간병 연결 플랫폼 · <strong>care-24 v2</strong></p><h1>병원별 간병 요청을<br>한곳에서 빠르게</h1><p>각 병원의 독립 웹·앱에서 보낸 간병인 신청과 환자·보호자 자료를 중앙 간병24가 통합 접수합니다.</p><div class="care-actions"><a class="primary" href="#request"><small>환자·보호자용</small>간병인 의뢰</a><a class="secondary" href="#matching"><small>간병인용</small>전국 상황판에서 신청</a></div></div><img src="assets/hichart.png" alt="H·CHART"></section><section class="promo-home card" aria-labelledby="promoHeading"><div><span class="badge">병원 홍보 영상</span><h2 id="promoHeading">3분 병원 홍보 Shorts</h2><p>병원의 진료·입원·찾아오는 길·간병 안내를 담은 공개 영상입니다.</p></div><a class="secondary" href="#promo-video">홍보 영상 등록</a><div id="promoVideos" class="promo-video-grid" aria-live="polite"><p>홍보 영상을 불러오는 중입니다.</p></div></section><h2>서비스 선택</h2><section class="grid service-grid"><article class="card service-card" onclick="location.hash='hospitals'"><span class="badge">전국 일반병원</span><h3 class="hospital-list-title directory-logo-title"><img src="assets/care24-brand.webp?v=20261003-logo2" alt="간병24" width="42" height="42"><span>전국병원 명단</span></h3><p>대학·종합·일반·전문·한방·호스피스·보훈병원</p></article><article class="card service-card nursing" onclick="location.hash='nursing'"><span class="badge">별도 웹·앱</span><h3>요양병원</h3><p>지역별·적정성평가 등급별 요양병원 찾기</p></article><article class="card service-card rehab" onclick="location.hash='rehab'"><span class="badge">별도 웹·앱</span><h3>재활병원</h3><p>지역별·재활의료기관 지정 구분으로 찾기</p></article><article class="card service-card secure-write-card" onclick="location.hash='secure-write'" role="button" tabindex="0" onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();location.hash='secure-write'}"><span class="home-write-icon" aria-hidden="true">✉</span><span class="badge">병원 담당자 전용</span><h3>병원 글쓰기</h3><p>대한노인돌봄서비스협회·간병24에 보안 전송</p></article></section><h2>주요 병원</h2><section class="grid">${hospitalCards(hospitals.slice(0,6))}</section><section class="card" style="margin-top:28px"><h3>모든 기기에서 사용</h3><p>PC에서는 웹으로, 갤럭시와 아이폰에서는 홈 화면에 설치해 앱처럼 사용할 수 있습니다.</p></section>`;loadPromoVideos();setupInstall()}
function promoList(){try{return JSON.parse(localStorage.getItem('care24-promo-videos')||'[]')}catch{return []}}
function loadPromoVideos(hospitalId=''){const box=document.querySelector('#promoVideos');if(!box)return;const items=promoList().filter(v=>!hospitalId||v.hospitalId===hospitalId);box.innerHTML=items.length?items.map(v=>`<article class="promo-video-card"><a href="${escapeHtml(v.url)}" target="_blank" rel="noopener noreferrer" aria-label="${escapeHtml(v.title)} 영상 열기"><span class="promo-play">▶</span></a><strong>${escapeHtml(v.hospitalName)}</strong><span>${escapeHtml(v.title)}</span></article>`).join(''):'<p class="promo-empty">등록된 병원 홍보 영상이 없습니다. 이 병원의 홍보 영상을 등록해 주세요.</p>'}
function promoVideo(){const rows=[...hospitals,...careFacilities];app.innerHTML=`<section class="panel"><a class="back" href="#home">← 홈</a><h2>병원 홍보 영상 등록</h2><p>첫 화면 상단에 표시할 공개 YouTube Shorts 영상을 등록합니다. 영상은 3분 이내로 제작하고, 환자 개인정보·진료기록·비공개 병실 정보는 포함하지 마세요.</p><form id="promoVideoForm" class="card form"><div class="field"><label for="promoHospital">병원</label><select id="promoHospital" required><option value="">병원을 선택하세요</option>${rows.map(h=>`<option value="${escapeHtml(h.id)}">${escapeHtml(h.name)}</option>`).join('')}</select></div><div class="field"><label for="promoTitle">영상 제목</label><input id="promoTitle" maxlength="100" required placeholder="예: 병원 입원·간병 안내"></div><div class="field"><label for="promoUrl">YouTube Shorts 주소</label><input id="promoUrl" type="url" maxlength="300" required placeholder="https://youtube.com/shorts/..."></div><button class="primary" type="submit">홍보 영상 등록</button></form><div id="promoVideoResult" aria-live="polite"></div></section>`;const form=document.querySelector('#promoVideoForm');form.onsubmit=e=>{e.preventDefault();const select=document.querySelector('#promoHospital'),h=rows.find(x=>x.id===select.value),result=document.querySelector('#promoVideoResult'),url=document.querySelector('#promoUrl').value.trim();if(!h||!/^https:\/\/(www\.)?(youtube\.com|youtu\.be)\//.test(url)){result.innerHTML='<p class="notice error">병원과 공개된 YouTube Shorts 주소를 확인해 주세요.</p>';return}const items=promoList();items.unshift({hospitalId:h.id,hospitalName:h.name,title:document.querySelector('#promoTitle').value.trim(),url});localStorage.setItem('care24-promo-videos',JSON.stringify(items.slice(0,6)));form.reset();result.innerHTML='<p class="notice success">이 기기의 첫 화면 상단에 홍보 영상이 등록되었습니다.</p>'}}function hospital(id){hospitalLanding(id)}
window.showDisease=(d,id)=>{document.querySelectorAll('.chip').forEach(x=>x.classList.toggle('active',x.textContent===d));document.querySelector('#diseaseBox').innerHTML=`<h3>${d}</h3><p>${d} 환자의 상태와 복약·식사·주의사항을 간병인에게 안전하게 전달하세요.</p>${d==='당뇨질환'?`<div class="actions"><a class="primary" href="https://www.hichart.net/sns/m/?shortenurl=KAdR" target="_blank" rel="noopener" style="text-decoration:none">H·CHART 자료 보기</a></div>`:''}<div class="actions"><button class="secondary" onclick="location.hash='request/${id}?d=${encodeURIComponent(d)}'">환자·보호자 의뢰</button></div>`}
function request(id){const h=hospitals.find(x=>x.id===id);const q=new URLSearchParams((location.hash.split('?')[1]||''));const d=q.get('d')||(h?.hospice?'호스피스·완화의료':'');const diseaseOptions=diseasesFor(h),caregiverOptions=caregiverOptionsFor(h);app.innerHTML=`<section class="panel"><a class="back" href="#${h?`hospital/${h.id}`:'home'}">← 돌아가기</a><h2>환자·보호자 의뢰</h2><nav class="patient-rehab-entry" aria-label="환자 재활교육"><a href="#rehabilitation${h?`?hospital=${encodeURIComponent(h.id)}`:''}" target="_blank" rel="noopener">재활치료(환자) <span aria-hidden="true">↗</span></a><small>작성 중인 의뢰서는 유지되고, 재활교육은 새 화면에서 열립니다.</small></nav>${h?`<p><a class="secondary" href="#board/${h.id}">간병 의뢰 · 간병 신청 상황판 →</a></p>`:""}<p>간병인 의뢰서: 필요한 질환별 간병과 희망 조건을 작성해 주세요.</p><form id="requestForm" class="card form"><div class="field"><label>병원</label><select name="hospital" required><option value="">병원을 선택하세요</option>${hospitals.map(x=>`<option value="${x.id}" ${h&&h.id===x.id?'selected':''}>${x.name}</option>`).join('')}</select></div><div class="field"><label>질환 구분</label><select name="disease"><option value="">선택 안 함</option>${diseaseOptions.map(x=>`<option ${x===d?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>간병인 유형</label><select name="caregiver" required><option value="일반 간병인">일반 간병인</option>${caregiverOptions.map(x=>`<option value="${x}">${x}</option>`).join('')}</select></div><div class="field"><label>환자·보호자 연락처</label><input name="phone" inputmode="tel" placeholder="010-0000-0000" required></div>${careLocationFields(h)}<div class="field"><label for="careStartDate">간병 시작일</label><input id="careStartDate" name="date" type="date" required></div><div class="field"><label for="careStartTime">간병 시작 시간 (한국 시간)</label><input id="careStartTime" name="time" type="time" step="60" required></div><div class="field"><label for="careEndDate">간병 종료일</label><input id="careEndDate" name="endDate" type="date" required></div><div class="field"><label for="careEndTime">간병 종료 시간 (한국 시간)</label><input id="careEndTime" name="endTime" type="time" step="60" required></div><div class="field"><label>전달사항</label><textarea name="memo" placeholder="환자 상태, 거동 가능 여부, 통증·투약·정서적 돌봄 주의사항 등"></textarea></div><label><input type="checkbox" required> 개인정보 수집·이용에 동의합니다.</label><div class="notice">호스피스 이용과 의료적 판단은 병원 호스피스팀과 상의해 주세요. 응급 증상은 119 또는 병원 의료진에게 즉시 알리고, 주민등록번호나 상세 진료기록은 입력하지 마세요.</div><button class="primary" type="submit">환자·보호자 의뢰 접수</button></form><div id="result"></div></section>`;bindApplication(document.querySelector('#requestForm'),'환자·보호자 의뢰',f=>findFacility(f.get('hospital')));enableCareReview(document.querySelector('#requestForm'),f=>findFacility(f.get('hospital')))}
